def parse_config(text):
    if not isinstance(text, str):
        raise ValueError
    result = {}
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError
        key, _, value = line.partition("=")
        key = key.strip()
        if not key or any(c.isspace() for c in key):
            raise ValueError
        value = value.strip()
        if len(value) >= 2 and value[0] in "\"'":
            quote = value[0]
            if value[-1] != quote:
                raise ValueError
            value = value[1:-1]
        elif value and value[0] in "\"'":
            raise ValueError
        else:
            if "#" in value:
                value = value.split("#", 1)[0].strip()
        if key in result:
            raise ValueError
        result[key] = value
    return result

